package io.github.headmaster218.recorder.android;
import android.content.*;import io.github.headmaster218.recorder.core.*;import java.nio.file.*;import java.util.*;
public final class HistoricalCleanupRequestTest {
 private static int checks;private static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 private static String fingerprint(FtpsQueue q){StringBuilder b=new StringBuilder();for(FtpsQueue.Item i:q.items(false))b.append(i.key).append('|').append(i.source).append('|').append(i.revision).append('|').append(i.wavHash).append('|').append(i.metadataHash).append('|').append(i.bytes).append('|').append(i.queuedAt).append('|').append(i.state).append('|').append(i.attempt).append('|').append(i.reconciliations).append('|').append(i.nextAt).append('|').append(i.uploadNow).append('|').append(i.detail).append('|').append(i.resultMetadataHash).append('|').append(i.markerHash).append('|').append(i.verifiedAt).append('|').append(i.cleanupState).append('|').append(Arrays.toString(i.cleanupBinding)).append('|').append(i.retirementGeneration).append('\n');return b.toString();}
 private static void rejected(FtpsQueue q,String revision,List<FtpsQueue.Item> rows,String reason)throws Exception{String before=fingerprint(q);boolean failed=false;try{q.requestHistoricalCleanup(revision,rows);}catch(java.io.IOException e){failed=true;}check(failed,reason+" rejected");check(before.equals(fingerprint(q)),reason+" entire batch unchanged");}
 private static void value(FtpsQueue q,long id,String key,Object value){ContentValues v=new ContentValues();if(value==null)v.putNull(key);else if(value instanceof String)v.put(key,(String)value);else if(value instanceof Long)v.put(key,(Long)value);else if(value instanceof Integer)v.put(key,(Integer)value);else if(value instanceof byte[])v.put(key,(byte[])value);else throw new AssertionError();check(q.getWritableDatabase().update("queue",v,"id=?",new String[]{String.valueOf(id)})==1,"test mutation");}
 private static List<FtpsQueue.Item> first(FtpsQueue q,int count){return new ArrayList<>(q.items(false).subList(0,count));}
 private static String receipt(FtpsQueue.Item i){return i.source+"|"+i.revision+"|"+i.attempt+"|"+i.bytes+"|"+i.wavHash+"|"+i.metadataHash+"|"+i.resultMetadataHash+"|"+i.markerHash+"|"+i.verifiedAt+"|"+i.queuedAt+"|"+i.reconciliations+"|"+i.state+"|"+i.uploadNow;}
 public static void main(String[] args)throws Exception{
  HistoryCapacityTest.main(args);FtpsQueue q=new FtpsQueue(new Context(Paths.get(args[0]).toFile()));String revision=q.current().revision;
  List<FtpsQueue.Item> selected=first(q,8);for(FtpsQueue.Item i:selected)check(FtpsQueue.historicalCleanupEligible(i,revision),"selected eligible");
  check(q.requestHistoricalCleanup(revision,selected)==8,"selected count returned");check(q.full(),"request alone does not claim reclaimed capacity");check(q.retirementCandidates().isEmpty(),"request does not invent cleanup completion");
  List<FtpsQueue.Item> after=first(q,9);for(int i=0;i<8;i++){check(after.get(i).cleanupState.equals("DEFERRED")&&after.get(i).cleanupBinding==null&&after.get(i).nextAt==0,"bounded row scheduled");check(receipt(after.get(i)).equals(receipt(selected.get(i))),"all receipt/attempt fields preserved");}check(!after.get(8).cleanupState.equals("DEFERRED"),"ninth not touched");
  q.close();q=new FtpsQueue(new Context(Paths.get(args[0]).toFile()));check(first(q,8).stream().allMatch(i->i.cleanupState.equals("DEFERRED")),"request survives reopen");q.revokeCleanup();check(q.cleanupRevision()==null,"revocation clears consent");check(first(q,8).stream().allMatch(i->i.cleanupState.equals("RETAINED")),"revocation returns selected originals to RETAINED");
  rejected(q,revision,first(q,2),"cleanup disabled");q.cleanupRevision(revision);q.pause(true);rejected(q,revision,first(q,2),"paused");q.pause(false);
  rejected(q,FtpsQueue.digest(new byte[]{9}),first(q,2),"wrong destination");rejected(q,revision,Collections.emptyList(),"empty");rejected(q,revision,null,"null");rejected(q,revision,first(q,9),"more than eight");FtpsQueue.Item one=first(q,1).get(0);rejected(q,revision,Arrays.asList(one,one),"duplicate IDs");
  List<FtpsQueue.Item> stale=first(q,2);value(q,stale.get(1).key,"verified_at",stale.get(1).verifiedAt+1);rejected(q,revision,stale,"one stale row rolls back all");
  String[] states={"BLOCKED","INTENT","QUARANTINED","PURGING","DEFERRED","RECHECKING","WAIT_SOURCE","REMOVED","RESTORED"};
  for(String state:states){one=first(q,1).get(0);value(q,one.key,"cleanup_state",state);check(!FtpsQueue.historicalCleanupEligible(first(q,1).get(0),revision),"excluded "+state);rejected(q,revision,first(q,2),state);value(q,one.key,"cleanup_state","RETAINED");}
  String[] fields={"attempt","result_metadata_hash","marker_hash","verified_at","bytes","source","wav_hash","metadata_hash","retirement_generation","cleanup_binding"};
  Object[] bad={"r-"+FtpsQueue.digest(new byte[]{8})+"-00000000000000000000000000000000",null,"bad",0L,0L,"bad-source","bad","bad",1L,new byte[]{1}};
  one=first(q,1).get(0);Object[] good={one.attempt,one.resultMetadataHash,one.markerHash,one.verifiedAt,one.bytes,one.source,one.wavHash,one.metadataHash,null,null};
  for(int n=0;n<fields.length;n++){value(q,one.key,fields[n],bad[n]);check(!FtpsQueue.historicalCleanupEligible(first(q,1).get(0),revision),"malformed "+fields[n]);rejected(q,revision,first(q,2),"malformed "+fields[n]);value(q,one.key,fields[n],good[n]);}
  for(long invalid:new long[]{1,44,47,Long.MAX_VALUE}){value(q,one.key,"bytes",invalid);check(!FtpsQueue.historicalCleanupEligible(first(q,1).get(0),revision),"invalid bounded WAV bytes");rejected(q,revision,first(q,2),"invalid WAV length");}value(q,one.key,"bytes",one.bytes);
  check(!FtpsQueue.historicalCleanupEligible(first(q,1).get(0),FtpsQueue.digest(new byte[]{7})),"predicate rejects wrong destination");
  value(q,one.key,"state","QUEUED");rejected(q,revision,first(q,2),"unverified row");value(q,one.key,"state","VERIFIED_AT_TIME");
  FtpsQueue.Profile other=q.save(new FtpsTransfer.Profile("other.invalid",21,"fixture","/history"),null);rejected(q,revision,first(q,2),"current saved profile changed");q.save(new FtpsTransfer.Profile("fixture.invalid",21,"fixture","/history"),null);
  FtpsQueue.Item second=first(q,2).get(1);value(q,second.key,"revision",other.revision);value(q,second.key,"source",one.source);value(q,second.key,"state","QUEUED");rejected(q,revision,Collections.singletonList(first(q,1).get(0)),"another destination needs source");value(q,second.key,"source",second.source);value(q,second.key,"revision",second.revision);value(q,second.key,"state",second.state);
  check(q.items(false).size()==500,"all detailed receipts retained");check(q.automaticRevision().equals(revision)&&q.automaticCapacityAt()==12345,"auto consent and capacity untouched");check(!q.paused(),"no unexpected pause mutation");q.close();System.out.println("PASS historical request API: "+checks+" assertions, including transactional rejection and revoke");
 }
}
